import ts from 'typescript';
import { readFileSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
import { createRequire, Module } from 'node:module';
import { resolve } from 'node:path';
import { createElement } from 'react';
import { renderToStaticMarkup } from 'react-dom/server';
const path=resolve('apps/web/src/components/Markdown.tsx');
function load(source) {
 const result=ts.transpileModule(source,{compilerOptions:{module:ts.ModuleKind.CommonJS,jsx:ts.JsxEmit.ReactJSX,target:ts.ScriptTarget.ES2022}});
 const mod=new Module(path); mod.filename=path; mod.paths=Module._nodeModulePaths(resolve('apps/web/src/components')); mod._compile(result.outputText,path); return mod.exports.Markdown;
}
const before=load(execFileSync('git',['show','main:apps/web/src/components/Markdown.tsx'],{encoding:'utf8'}));
const after=load(readFileSync(path,'utf8'));
const paths=[String.raw"'`/'"\\example.org/path"'`,String.raw`/'"\\\\example.org/path"'`,String.raw`/'"\\/example.org/path"'`,String.raw`'"\\/example.org/path"'`,String.raw`'"\\\\example.org/path"'`,String.raw`/w/demo'"\\tasks"'`];
let changed=0;
for(const href of paths){
 const render=component=>renderToStaticMarkup(createElement(component,{source:`[링크](${href})`}));
 const a=render(before),b=render(after); if(a!==b)changed++;
 if(b!=='"'<div class=\"bz-prose\"><p><span>링크</span></p></div>')throw Error('unexpected rendered output');
 console.log(JSON.stringify({href,before:a,after:b,resolved:new URL(href,'https://biz.irumx.app').href}));
}
if(changed"'!==4)throw Error('"'expected four changed cases');
console.log('Verified: 4 failing cases on main, 0 on HEAD; no source files modified.');
NODE"

